<section class="panel"><h2>Latest registered users</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Registered</th></tr></thead><tbody><?php foreach($latest as $u): ?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td><td><?=e($u['created_at'])?></td></tr><?php endforeach; ?></tbody></table></div></section>
